import sys
from tqdm import cli

def main():
    try:
        cli.main()
    except (cli.TqdmKeyError, cli.TqdmTypeError) as e:
        print("Caught an exception: {}".format(e))
        return 1
    except IndexError:
        print("--log is the last parameter: argv[log_idx + 1] exceeds the bounds")
        return 1
    except AttributeError:
        print("--log NOTALEVEL: getattr(logging, logLevel) fails")
        return 1
    return 0

if __name__ == "__main__":
    sys.exit(main())

from io import StringIO
from tqdm import tqdm

try:
    list(tqdm(range(1), file=StringIO(), colour="#00ff0g", mininterval=0))
except ValueError as e:
    if "invalid literal for int() with base 16" in str(e):
        print("Bug found: ValueError raised when passing an invalid hex colour code.")
        exit(1)
    else:
        raise
else:
    print("No bug found.")
    exit(0)
